// [any-thread] SwiftUI runs button actions on the main actor, so these run
// on the main thread in practice; they only ever touch input_snapshot the
// same way MvMetalView's event handlers do (edge-triggered counter bump,
// then wake), so there is nothing here that requires it.
extern "C" void mv_chrome_fit(void) {
  if (!g_chrome_snap) return;
  ++g_chrome_snap->fit_seq;
  // publish(), not just wake(): input_snapshot flows through a triple-buffer
  // publish_slot (core/spsc_ring.h) — the render thread only sees this bump
  // once publish() copies the snapshot in, same as every MvMetalView handler.
  if (g_chrome_lab) g_chrome_lab->publish(*g_chrome_snap);
  if (g_chrome_lab) g_chrome_lab->wake();
}
extern "C" void mv_chrome_one_to_one(void) {
  if (!g_chrome_snap) return;
  ++g_chrome_snap->one_to_one_seq;
  if (g_chrome_lab) g_chrome_lab->publish(*g_chrome_snap);
  if (g_chrome_lab) g_chrome_lab->wake();
}

// CMake's project(VERSION), the same number Windows puts in VERSIONINFO.
// Empty when this file is compiled outside the host targets.
#ifndef MV_APP_VERSION
#define MV_APP_VERSION ""
#endif

extern "C" bool mv_chrome_app_version(char* buf, int32_t size) {
  if (!buf || size <= 0) return false;
  constexpr const char* version = MV_APP_VERSION;
  if (version[0] == '\0') {
    buf[0] = '\0';
    return false;
  }
  const std::size_t n = std::min(std::strlen(version), static_cast<std::size_t>(size) - 1);
  std::memcpy(buf, version, n);
  buf[n] = '\0';
  return true;
}

