  // docs/design/25: the theme's canvas colours, when a theme is on.
  BOOL _themeCanvasActive;
  BOOL _themeHasDark;
  BOOL _themeHasLight;
  uint32_t _themeDarkRgb;
  uint32_t _themeLightRgb;

  // Issue #38: the clip transport's idle state (shell/transport_autohide.h, the
